INSERT OR REPLACE INTO programs (id, name, theme_concept, active) VALUES ('week1', 'Transit Cycle 01', 'MERIDIAN // OPS — long-haul transit vessel systems terminal', 1);
INSERT OR REPLACE INTO categories (id, program_id, name, label, kind, sort_order) VALUES ('week1-propulsion', 'week1', 'propulsion', 'PROPULSION', 'sets', 0);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-1-tuesday-upper-body-bench-press', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Bench press', 'Empty barbell (35 lb) only this week — focus: shoulder blades pinned, controlled descent to chest', '{"targetText":"3 x 8"}', 0);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-1-tuesday-upper-body-powerblock-row-bent-over-or-single-arm', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Powerblock row (bent over or single-arm)', '20-25 lb — squeeze shoulder blade, don''t yank with momentum', '{"targetText":"3 x 10"}', 1);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-1-tuesday-upper-body-kettlebell-overhead-press-seated-or-stan', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Kettlebell overhead press (seated or standing)', '10-15 lb — press straight up, don''t lean back. **Alternative:** since you can OHP the empty 35lb barbell for a few reps, feel free to use that instead 1-2x this week to see how it feels — or the fixed 15-20lb barbell as a middle option', '{"targetText":"3 x 8/side"}', 2);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-1-tuesday-upper-body-pull-up-bar-dead-hang-scap-pulls', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Pull-up bar: dead hang + scap pulls', 'Bodyweight — this builds shoulder stability before real pull-ups. **Given your trap/neck tendency:** keep shoulders pulled down away from ears the whole hang, don''t let them shrug up — if your neck/traps start to feel it, shorten the hang time rather than pushing through', '{"targetText":"3 x max hang (aim 15-20 sec) + 8 scap pulls"}', 3);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-1-tuesday-upper-body-push-up-progression', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Push-up progression', 'Incline push-ups: hands on the bench, feet on floor, **hands set wide** (you already know this helps you). Lower chest to bench, controlled. **Skip the knee push-up regression entirely** — with hypermobile kneecaps, kneeling on the floor under load isn''t worth it. Instead, progress by lowering the incline height (bench → lower surface → floor) rather than moving to your knees', '{"targetText":"3 x max effort (aim 5-8)"}', 4);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-1-tuesday-upper-body-pulley-face-pulls', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Pulley face pulls', 'Light band/plate tension — elbows high, squeeze shoulder blades. **Given your trap/neck tendency:** keep the movement in the shoulder blades, not the neck/traps — if you feel it creeping into your neck, drop the tension further', '{"targetText":"3 x 15"}', 5);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-1-tuesday-upper-body-dumbbell-bicep-curl-tricep-pushdown-pull', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Dumbbell bicep curl + tricep pushdown (pulley)', 'EZ curl bar for curls (easier wrist angle than straight dumbbell curls, worth using given the hypermobility) + light pulley tension for pushdowns', '{"targetText":"2 x 12 each"}', 6);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-2-wednesday-lower-body-technique-day-kettlebell-goblet-squat', 'week1-propulsion', 'Day 2 (Wednesday) — Lower Body (technique day)', 'Kettlebell goblet squat', '15-20 lb held at chest, **heels on squat wedges.** This is your main squat pattern this week, NOT the barbell. The wedges reduce how much ankle mobility you need to stay upright — if the forward lean was partly an ankle range issue, this alone may fix a lot of it. Sit back like sitting in a chair, chest up, weight even through the foot', '{"targetText":"4 x 8"}', 7);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-2-wednesday-lower-body-technique-day-barbell-squat-empty-bar-only', 'week1-propulsion', 'Day 2 (Wednesday) — Lower Body (technique day)', 'Barbell squat (empty bar only)', '35 lb only, **heels on wedges, standing on the plywood platform.** Purely to practice bar position on back + the same upright-torso cue as the goblet squat, low reps', '{"targetText":"2 x 5"}', 8);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-2-wednesday-lower-body-technique-day-kettlebell-rdl-romanian-deadlift', 'week1-propulsion', 'Day 2 (Wednesday) — Lower Body (technique day)', 'Kettlebell RDL / Romanian deadlift', '20-25 lb — hinge at hips, slight knee bend, feel hamstrings stretch, flat back. **Alternative:** since you have 2lb practice plates + 10lb plates, you could use the empty barbell (35lb) as a light RDL instead and add small increments over coming weeks — this lets you progress in much smaller jumps than jumping between kettlebell weights, which is genuinely useful given the hypermobility (smaller, more controllable load increases)', '{"targetText":"3 x 10"}', 9);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-2-wednesday-lower-body-technique-day-glute-bridge', 'week1-propulsion', 'Day 2 (Wednesday) — Lower Body (technique day)', 'Glute bridge', 'If you don''t feel this in your glutes (common), try: feet closer to your hips, a resistance band looped just above your knees (push knees out against the band), and pause 2 sec at the top squeezing hard. If it''s still not landing, this exercise can be dropped for now — feeling it matters more than doing it', '{"targetText":"3 x 12"}', 10);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-2-wednesday-lower-body-technique-day-split-squat-rear-foot-elevated-optional', 'week1-propulsion', 'Day 2 (Wednesday) — Lower Body (technique day)', 'Split squat (rear foot elevated optional)', 'Bodyweight or light dumbbells (5-8 lb each hand) — this covers the unilateral leg work walking lunges would, without needing lunge-length floor space', '{"targetText":"2 x 10/side"}', 11);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-2-wednesday-lower-body-technique-day-standing-calf-raise', 'week1-propulsion', 'Day 2 (Wednesday) — Lower Body (technique day)', 'Standing calf raise', 'Bodyweight', '{"targetText":"3 x 15"}', 12);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-4-friday-upper-body-volume-day-powerblock-incline-press-feet-up-on-benc', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Powerblock incline press (feet up on bench or use floor angle)', '15-20 lb each hand', '{"targetText":"3 x 10"}', 13);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-4-friday-upper-body-volume-day-pulley-seated-row', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Pulley seated row', 'Moderate tension — squeeze at the back, controlled return', '{"targetText":"3 x 12"}', 14);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-4-friday-upper-body-volume-day-powerblock-lateral-raise', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Powerblock lateral raise', '5-8 lb — light, controlled, no swinging', '{"targetText":"3 x 12"}', 15);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-4-friday-upper-body-volume-day-negative-pull-ups-jump-to-top-lower-slow', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Negative pull-ups (jump to top, lower slow 3-5 sec)', 'Bodyweight — builds toward real pull-ups', '{"targetText":"3 x 3-5"}', 16);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-4-friday-upper-body-volume-day-push-up-progression', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Push-up progression', 'Same incline push-up as Monday — lower the incline (e.g., a lower surface) once 8+ reps feel easy at current height', '{"targetText":"3 x max effort"}', 17);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-4-friday-upper-body-volume-day-kettlebell-suitcase-carry', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Kettlebell suitcase carry', '20-25 lb — given the tight space, do this as a slow walk on the treadmill instead (very low speed, ~1 mph), holding the kettlebell at your side, core braced', '{"targetText":"3 x 20 steps/side"}', 18);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-4-friday-upper-body-volume-day-dumbbell-hammer-curl', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Dumbbell hammer curl', '8-12 lb', '{"targetText":"2 x 12"}', 19);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-5-saturday-lower-body-volume-day-kettlebell-goblet-squat', 'week1-propulsion', 'Day 5 (Saturday) — Lower Body (volume day)', 'Kettlebell goblet squat', '15-20 lb — same cues as Tuesday', '{"targetText":"3 x 10"}', 20);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-5-saturday-lower-body-volume-day-kettlebell-deadlift-standing-over-kb-or-', 'week1-propulsion', 'Day 5 (Saturday) — Lower Body (volume day)', 'Kettlebell deadlift (standing over KB, or sumo stance)', '25-30 lb — hinge, flat back, drive through heels. **Stand on the plywood platform if it fits your stance**, otherwise plain carpet is fine here since it''s a lighter, more controlled lift than the squat', '{"targetText":"3 x 8"}', 21);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-5-saturday-lower-body-volume-day-walking-lunge', 'week1-propulsion', 'Day 5 (Saturday) — Lower Body (volume day)', 'Walking lunge', 'Given tight space, do **reverse lunges in place** instead (step back, not forward — needs less room, and is generally easier to balance for hypermobile knees since there''s less forward knee travel)', '{"targetText":"3 x 10/side"}', 22);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-5-saturday-lower-body-volume-day-hip-thrust-feet-on-floor-shoulders-on-be', 'week1-propulsion', 'Day 5 (Saturday) — Lower Body (volume day)', 'Hip thrust (feet on floor, shoulders on bench)', 'If you don''t feel this either (also common), try: band above the knees pushing out, feet a bit closer to your hips, chin tucked (not thrown back), and pause hard at the top. Same rule as the glute bridge — if it''s still not landing after trying these tweaks, it''s fine to drop for now', '{"targetText":"3 x 12"}', 23);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-5-saturday-lower-body-volume-day-side-lying-leg-raise-or-band-walk', 'week1-propulsion', 'Day 5 (Saturday) — Lower Body (volume day)', 'Side-lying leg raise or band walk', 'Hip stability — helpful for knee tracking in squat', '{"targetText":"2 x 15/side"}', 24);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-5-saturday-lower-body-volume-day-plank', 'week1-propulsion', 'Day 5 (Saturday) — Lower Body (volume day)', 'Plank', 'Bodyweight', '{"targetText":"3 x 20-30 sec"}', 25);
INSERT OR REPLACE INTO categories (id, program_id, name, label, kind, sort_order) VALUES ('week1-fuel-cells', 'week1', 'fuel-cells', 'FUEL CELLS', 'checkbox', 1);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-mon-lunch-tofu-chickpea-bowl', 'week1-fuel-cells', 'Mon', 'Tofu & Chickpea Bowl (lunch)', '540 kcal / 32g', '{"mealType":"lunch","day":"Mon","recipe":{"key":"mon-lunch","title":"Tofu & Chickpea Bowl","ingredients":["200g extra-firm tofu, pressed, cubed","1 tbsp soy sauce","1 tbsp cornstarch","1 cup canned chickpeas, drained and patted dry","1 tsp olive oil","Pinch salt, paprika (optional, for chickpeas)","200g roasted sweet potato (from your batch)","1 cup roasted veggies (broccoli/peppers)","1-1.5 tbsp tahini","Juice of 1/2 lemon","1-2 tbsp water","Pinch salt (for dressing)"],"steps":["Toss tofu cubes with soy sauce, then cornstarch until coated.","Toss chickpeas with olive oil, salt, and paprika.","Air fry tofu at 400°F for 12 min, shaking halfway. Air fry chickpeas at 400°F for 10-12 min, shaking halfway (separate batch or a second basket if you have one).","Whisk tahini, lemon juice, water, and a pinch of salt until smooth — add more water if too thick.","Warm the sweet potato and roasted veggies (microwave 1-2 min, or air fryer 3-4 min).","Assemble: sweet potato and veggies as the base, top with tofu and chickpeas, drizzle with tahini sauce."]}}', 0);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-mon-dinner-tofu-steaks', 'week1-fuel-cells', 'Mon', 'Tofu Steaks (dinner)', '480 kcal / 30g', '{"mealType":"dinner","day":"Mon","recipe":{"key":"mon-dinner","title":"Tofu Steaks","ingredients":["200g extra-firm tofu, pressed, sliced into 3-4 slabs","1 tbsp soy sauce","1 tsp ginger-garlic paste","2 cups broccoli and carrots, chopped","1 tsp olive oil","Salt, pepper","2/3 cup cooked farro"],"steps":["Marinate tofu slices in soy sauce and ginger-garlic paste for at least 10 minutes.","Air fry tofu at 400°F for 15 min, flipping halfway.","Toss broccoli and carrots with olive oil, salt, and pepper. Air fry at 400°F for 12-15 min (run this batch before or after the tofu if your basket is small).","Cook farro ahead of time per package directions, or in the pressure cooker: 1 part farro to 2 parts water, high pressure 10 min, quick release.","Plate tofu and veggies over the farro."]}}', 1);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-tue-lunch-ground-turkey-taco-bowl', 'week1-fuel-cells', 'Tue', 'Ground Turkey Taco Bowl (lunch)', '550 kcal / 34g', '{"mealType":"lunch","day":"Tue","recipe":{"key":"tue-lunch","title":"Ground Turkey Taco Bowl","ingredients":["150g ground turkey","1/2 tsp chili powder","1/2 tsp paprika","1/2 tsp dried oregano","Pinch salt","2/3 cup cooked rice","1/2 cup black beans","Handful shredded lettuce","2 tbsp salsa","1/4 avocado, sliced"],"steps":["Heat a nonstick pan over medium-high heat. Add turkey, breaking it up with a spatula as it cooks.","Season with chili powder, paprika, oregano, and salt. Cook 8-10 min until browned through (internal temp 165°F).","Warm the black beans separately (microwave or small pot, 2-3 min).","Build the bowl: rice on the bottom, turkey and beans on top, then lettuce, salsa, and avocado."]}}', 2);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-tue-dinner-ground-beef-veggie-stir-fry', 'week1-fuel-cells', 'Tue', 'Ground Beef & Veggie Stir-Fry (dinner)', '560 kcal / 26g', '{"mealType":"dinner","day":"Tue","recipe":{"key":"tue-dinner","title":"Ground Beef & Veggie Stir-Fry","ingredients":["150g Walden Local 80/20 ground beef","2 cups mixed stir-fry veggies (fresh or frozen)","1 tbsp soy sauce","1 tsp ginger-garlic paste","1/2 tsp sesame oil (optional)","2/3 cup cooked rice"],"steps":["Brown the beef in a pan over medium-high heat, breaking it apart, about 6-8 min.","Drain the fat (tilt the pan and spoon it off, or transfer to a strainer and rinse briefly with hot water for a leaner result).","Add the ginger-garlic paste, cook 30 seconds until fragrant.","Add the veggies and soy sauce, stir-fry 4-5 min until crisp-tender.","Serve over rice."]}}', 3);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-wed-lunch-chickpea-salad', 'week1-fuel-cells', 'Wed', 'Chickpea Salad (lunch)', '480 kcal / 22g', '{"mealType":"lunch","day":"Wed","recipe":{"key":"wed-lunch","title":"Chickpea Salad","ingredients":["2 cups mixed greens","1.5 cups chickpeas, drained and rinsed","1/2 cucumber, sliced","2 tbsp lactose-free feta or a handful of olives","1 tbsp olive oil","1 tbsp vinegar (red wine or apple cider)","Salt, pepper"],"steps":["Combine greens, chickpeas, cucumber, and feta or olives in a bowl.","Whisk olive oil, vinegar, salt, and pepper. Drizzle over the salad and toss."]}}', 4);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-wed-dinner-chana-masala', 'week1-fuel-cells', 'Wed', 'Chana Masala (dinner)', '500 kcal / 25g', '{"mealType":"dinner","day":"Wed","recipe":{"key":"wed-dinner","title":"Chana Masala","ingredients":["1.75 cups canned chickpeas, drained","1/2 onion, diced","1-2 tsp ginger-garlic paste","1 cup canned diced tomatoes","1 tsp turmeric","1 tsp garam masala","1/2 tsp ground coriander","1 tbsp oil","Salt to taste","2/3 cup cooked rice"],"steps":["Sauté mode: heat oil, add onion, cook 3-4 min until soft.","Add ginger-garlic paste, cook 30 sec.","Add tomatoes, turmeric, garam masala, coriander, and salt. Stir.","Add chickpeas and 1/4 cup water. Seal, cook on high pressure 5 min, natural release 5 min, then quick release.","Serve over rice."]}}', 5);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-thu-lunch-red-lentil-dal', 'week1-fuel-cells', 'Thu', 'Red Lentil Dal (lunch)', '480 kcal / 24g', '{"mealType":"lunch","day":"Thu","recipe":{"key":"thu-lunch","title":"Red Lentil Dal","ingredients":["3/4 cup dry red lentils, rinsed","1.5 cups water or broth","1/2 onion, diced","1 tsp ginger-garlic paste","1/2 tsp turmeric","1/2 tsp garam masala","1/4 tsp ground coriander","1 tbsp oil","Salt to taste","2/3 cup cooked rice"],"steps":["Sauté mode: cook onion in oil, 3-4 min.","Add ginger-garlic paste, turmeric, garam masala, and coriander, cook 30 sec.","Add rinsed lentils and water/broth. Seal, cook on high pressure 5 min, natural release 10 min.","Stir, season with salt, serve over rice."]}}', 6);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-thu-dinner-turkey-meatballs-marinara', 'week1-fuel-cells', 'Thu', 'Turkey Meatballs + Marinara (dinner)', '500 kcal / 40g', '{"mealType":"dinner","day":"Thu","recipe":{"key":"thu-dinner","title":"Turkey Meatballs + Marinara","ingredients":["150g ground turkey","Salt, pepper, 1/2 tsp dried oregano","1 cup marinara sauce","2oz Barilla Protein+ pasta (or zucchini noodles)"],"steps":["Mix ground turkey with oregano, salt, and pepper. Form into 4-5 meatballs.","Air fry at 380°F for 10-12 min, turning halfway, until internal temp reaches 165°F.","Warm marinara in a small pot while the meatballs cook.","Cook pasta per package directions, or sauté spiralized zucchini 2-3 min.","Combine meatballs with marinara, serve over pasta or zoodles."]}}', 7);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-fri-lunch-meatball-bowl', 'week1-fuel-cells', 'Fri', 'Meatball Bowl (lunch)', '520 kcal / 33g', '{"mealType":"lunch","day":"Fri","recipe":{"key":"fri-lunch","title":"Meatball Bowl","ingredients":[],"steps":[]}}', 8);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-fri-dinner-black-bean-tacos', 'week1-fuel-cells', 'Fri', 'Black Bean Tacos (dinner)', '480 kcal / 20g', '{"mealType":"dinner","day":"Fri","recipe":{"key":"fri-dinner","title":"Black Bean Tacos","ingredients":["1.25 cups canned black beans, drained","1/2 tsp chili powder","1/2 tsp paprika","Pinch salt","3 corn tortillas","1/4 avocado, sliced","2 tbsp salsa","Lactose-free sour cream"],"steps":["Warm the black beans in a small pot with chili powder, paprika, and salt, mashing lightly with a fork if you want a thicker texture, about 5 min.","Warm the tortillas in a dry pan (30 sec per side) or microwave wrapped in a damp paper towel (30 sec).","Fill tortillas with beans, top with avocado, salsa, and sour cream."]}}', 9);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-sat-lunch-repeat-any-favorite', 'week1-fuel-cells', 'Sat', 'Repeat any favorite (lunch)', NULL, '{"mealType":"lunch","day":"Sat"}', 10);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-sat-dinner-repeat-any-favorite', 'week1-fuel-cells', 'Sat', 'Repeat any favorite (dinner)', NULL, '{"mealType":"dinner","day":"Sat"}', 11);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-sun-lunch-repeat-any-lunch', 'week1-fuel-cells', 'Sun', 'Repeat any lunch (lunch)', NULL, '{"mealType":"lunch","day":"Sun"}', 12);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-sun-dinner-white-bean-veggie-soup', 'week1-fuel-cells', 'Sun', 'White Bean & Veggie Soup (dinner)', '460 kcal / 23g', '{"mealType":"dinner","day":"Sun","recipe":{"key":"sun-dinner","title":"White Bean & Veggie Soup","ingredients":["1.75 cups canned white beans, drained","2 cups chopped kale","1 cup canned diced tomatoes","1/2 onion, diced","1 tsp minced garlic","2 cups broth or water","1 tbsp olive oil","Salt, pepper, dried oregano to taste","1 slice whole grain bread"],"steps":["Sauté mode: heat olive oil, add onion and garlic, cook 3 min.","Add tomatoes, beans, kale, broth, salt, pepper, and oregano.","Seal, cook on high pressure 8-10 min, then release.","Serve with the bread."]}}', 13);
INSERT OR REPLACE INTO categories (id, program_id, name, label, kind, sort_order) VALUES ('week1-life-support', 'week1', 'life-support', 'LIFE SUPPORT', 'checkbox', 2);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-life-support-daily-with-breakfast-or-mid-morning-snack', 'week1-life-support', NULL, 'With breakfast (or mid-morning snack)', 'Multi + Omega-3 (Women''s), B-12 — Take with food for better absorption', NULL, 0);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-life-support-daily-with-lunch', 'week1-life-support', NULL, 'With lunch', 'Calcium + D3 gummies — Separate from iron by a few hours (calcium blocks iron absorption)', NULL, 1);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-life-support-daily-with-dinner-or-evening', 'week1-life-support', NULL, 'With dinner or evening', 'Probiotic — Consistency matters more than exact timing — same time daily is the main thing', NULL, 2);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-life-support-daily-only-on-days-you-haven-t-had-much-red-me', 'week1-life-support', NULL, 'Only on days you haven''t had much red meat', 'Iron — Take with a vitaminC-containing food (citrus, berries) for better absorption, and **away from the calcium gummies and any Metamucil** by a few hours', NULL, 3);
